From e50a68014d0f5206e5d69028eb2e83ebfefa985e Mon Sep 17 00:00:00 2001
From: Richard Hansen <rhansen@bbn.com>
Date: Fri, 15 Jan 2016 03:04:40 -0500
Subject: [PATCH] fix getting pointer to pointer to start of array

According to the C standard, if foo is an array type, foo can also be
used as a pointer to the first element in the array in many contexts.
However, unlike an actual pointer, &foo does not get the address of
the address of the first element; it is the same as foo without the &.

This fixes a bug introduced in b9d846a.

diff --git a/lib/rpki/tests/roa_test/roa_test.c b/lib/rpki/tests/roa_test/roa_test.c
index 3f3d4fc7..fc45c0cd 100644
--- a/lib/rpki/tests/roa_test/roa_test.c
+++ b/lib/rpki/tests/roa_test/roa_test.c
@@ -90,6 +90,7 @@ int main(
     char *filename_cnf = NULL;
     char *ski;
     char fn[PATH_MAX];
+    char *fnp = &fn[0];
     int sta = 0;

     CMS(&roa, (ushort) 0);
@@ -148,7 +149,7 @@ int main(
         freescm(scmp);
         return -4;
     }
-    cert = (X509 *)roa_parent(scmp, conp, ski, &fn, &sta);
+    cert = (X509 *)roa_parent(scmp, conp, ski, &fnp, &sta);
     disconnectscm(conp);
     freescm(scmp);
     free(ski);
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fix getting pointer to pointer to start of array

According to the C standard, if foo is an array type, foo can also be
used as a pointer to the first element in the array in many contexts.
However, unlike an actual pointer, &foo does not get the address of
the address of the first element; it is the same as foo without the &.

This fixes a bug introduced in b9d846a.

Here is the root cause:
The bug arises from a misunderstanding of how array types and pointers work in C. Specifically, using `&fn` (where `fn` is an array) does not yield a pointer to the first element's address as expected; instead, it provides the same address as `fn`. This leads to incorrect pointer handling when passing the address to the `roa_parent` function, which expects a pointer to a pointer. The fix involves using a separate pointer variable (`fnp`) to correctly reference the address of the first element of the array.

Here is the patch:

 int main(
     int argc,
     char **argv)
 {
     struct CMS roa;
     struct CMS roa2;
     unsigned char *blob = NULL;
     FILE *fp = NULL;
     scmcon *conp;
     scm *scmp;
     X509 *cert;
     char filename_der[16] = "";
     char filename_pem[16] = "";
     char errmsg[1024];
     char *filename_cnf = NULL;
     char *ski;
     char fn[PATH_MAX];
+    char *fnp = &fn[0];
     int sta = 0;

     CMS(&roa, (ushort) 0);
     CMS(&roa2, (ushort) 0);
     if (argc < 2)
         filename_cnf = "roa.cnf";
     else
         filename_cnf = argv[1];
     strncpy(filename_der, "mytest.roa.der", sizeof(filename_der) - 1);
     strncpy(filename_pem, "mytest.roa.pem", sizeof(filename_pem) - 1);
     sta = roaFromConfig(filename_cnf, 0, &roa);
     if (sta < 0)
     {
         (void)fprintf(stderr, "roaFromConfig(%s) failed with error %s (%d)\n",
                       filename_cnf, err2string(sta), sta);
         return sta;
     }
     sta = roaToFile(&roa, filename_pem, FMT_PEM);
     delete_casn(&roa.self);
     if (sta < 0)
     {
         (void)fprintf(stderr, "roaToFile(%s) failed with error %s (%d)\n",
                       filename_pem, err2string(sta), sta);
         return sta;
     }
     sta = roaFromFile(filename_pem, FMT_PEM, cTRUE, &roa2);
     if (sta < 0)
     {
         (void)fprintf(stderr, "roaFromFile(%s) failed with error %s (%d)\n",
                       filename_pem, err2string(sta), sta);
         return sta;
     }
     ski = (char *)roaSKI(&roa2);
     if (ski == NULL || ski[0] == 0)
     {
         (void)fprintf(stderr, "ROA has NULL SKI\n");
         return -2;
     }
     scmp = initscm();
     if (scmp == NULL)
     {
         delete_casn(&roa2.self);
         free(ski);
         (void)fprintf(stderr,
                       "Internal error: cannot initialize database schema\n");
         return -3;
     }
     memset(errmsg, 0, 1024);
     conp = connectscm(scmp->dsn, errmsg, 1024);
     if (conp == NULL)
     {
         (void)fprintf(stderr, "Cannot connect to DSN %s: %s\n",
                       scmp->dsn, errmsg);
         delete_casn(&roa2.self);
         free(ski);
         freescm(scmp);
         return -4;
     }
-    cert = (X509 *)roa_parent(scmp, conp, ski, &fn, &sta);
+    cert = (X509 *)roa_parent(scmp, conp, ski, &fnp, &sta);
     disconnectscm(conp);
     freescm(scmp);
     free(ski);
     if (cert == NULL)
     {
         (void)fprintf(stderr,
                       "ROA certificate has no parent in DB: error %s (%d)\n",
                       err2string(sta), sta);
         delete_casn(&roa2.self);
         return sta;
     }
     blob = myreadfile(fn, &sta);
     if (blob == NULL)
     {
         (void)fprintf(stderr,
                       "Cannot read certificate from %s: error %s (%d)\n", fn,
                       err2string(sta), sta);

         X509_free(cert);
         delete_casn(&roa2.self);
         return (sta);
     }
     sta = roaValidate2(&roa2);
     free((void *)blob);
     X509_free(cert);
     if (sta < 0)
     {
         (void)fprintf(stderr,
                       "ROA failed semantic validation: error %s (%d)\n",
                       err2string(sta), sta);
         delete_casn(&roa2.self);
         return sta;
     }
     fp = fopen("roa.txt", "a");
     if (fp == NULL)
     {
         (void)fprintf(stderr, "Cannot open roa.txt\n");
         delete_casn(&roa2.self);
         return -5;
     }
     sta = roaGenerateFilter(&roa2, NULL, fp, NULL, 0);
     delete_casn(&roa2.self);
     (void)fclose(fp);
     if (sta < 0)
     {
         (void)fprintf(stderr,
                       "Cannot generate ROA filter output: error %s (%d)\n",
                       err2string(sta), sta);
         return sta;
     }
     return 0;
 }
-- 


